function pa_admin_url(array $extra=[]): string { global $filter,$q,$p; return 'feedback.php?'.http_build_query(array_merge(['status'=>$filter,'q'=>$q,'p'=>$p],$extra)); }
extract((new AdminFeedbackController())->feedback(), EXTR_OVERWRITE);
